## Function

```js
// Converts US/Canada (NANP) phone numbers to E.164, or returns null if invalid.
// Extensions (e.g. "x123", "ext. 5") are treated as invalid: the trailing
// letters/digits can't be represented in E.164, and stripping them would guess.
function toE164(input) {
  if (typeof input !== 'string') return null;
  const s = input.trim();
  // Only digits and common separators are allowed; letters (incl. extensions) fail.
  if (!/^\+?[\d\s().-]+$/.test(s)) return null;
  // A '+' is only valid as a leading "+1".
  if (s.includes('+') && !/^\+\s*1(?!\d*\+)/.test(s)) return null;
  const digits = s.replace(/\D/g, '');
  let national;
  if (digits.length === 10 && !s.startsWith('+')) national = digits;
  else if (digits.length === 11 && digits[0] === '1') national = digits.slice(1);
  else return null;
  // NANP: area code and exchange must start with 2-9.
  if (!/^[2-9]\d{2}[2-9]\d{6}$/.test(national)) return null;
  return '+1' + national;
}
```

